using System;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "CriticalEffect", menuName = "Data/Battle/Effects/Austra/Critical Effect")]
public class CriticalEffect : Effect
{
	[Header("Critical Multiplier")]
	[SerializeField]
	private Effect criticalMultiplierEffect;

	[SerializeField]
	private int criticalMultiplierStartingAmount;

	[SerializeField]
	private Effect criticalMultiplierConfuseEffect;

	[Header("Critical Omens")]
	[SerializeField]
	private CelestialDewOmenData celestialDewOmenData;

	[NonSerialized]
	public bool CriticalIridescentLight;

	[NonSerialized]
	public bool CriticalSafeDie;

	[NonSerialized]
	public bool CriticalMultiplierConfuseAction;

	protected override string GetEffectDescriptionWithAmountReplacedWithX(string localizedDescription, int amount, GameObject effectOwner)
	{
		return GetEffectDescriptionWithAmountReplacedWithX(localizedDescription, GetNumberToReplaceWithX(), GetCriticalMultiplierAmount());
	}

	protected override string GetEffectDescriptionWithAmount(int amount, GameObject effectOwner)
	{
		return Smart.Format(GetLocalizedDescription(), amount, GetCriticalMultiplierAmount());
	}

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		CriticalIridescentLight = false;
		CriticalSafeDie = false;
		CriticalMultiplierConfuseAction = false;
	}

	public int GetPurifyAmount(int chanceAmount, int purifyAmount, PlayerEffects playerEffects, bool fierceSquall, bool sentPur, GameObject source = null)
	{
		bool flag = playerEffects.IsPlayerHurricane();
		bool flag2 = false;
		if (!CriticalIridescentLight && !flag)
		{
			flag2 = playerEffects.IsPlayerEolicDivinationAndDecreaseIt();
			if (flag2)
			{
				chanceAmount = 100;
			}
			else if (source != null)
			{
				Debug.Log("chanceAmount before hive module: " + chanceAmount);
				chanceAmount += ReferenceSingleton<AustraOmensHandler>.Instance.IsHiveModuleOmenActivateGetCriticalChanceModifierAmount();
				Debug.Log("chanceAmount after hive module: " + chanceAmount);
				chanceAmount = Mathf.Min(chanceAmount, 100);
				Debug.Log("chanceAmount final: " + chanceAmount);
			}
		}
		if (RandomUtilities.RandomChance(chanceAmount) || CriticalIridescentLight || flag)
		{
			if (!CriticalIridescentLight && !flag && !flag2)
			{
				if (fierceSquall)
				{
					playerEffects.IsPlayerFierceSquall(activateFeedback: true);
				}
				else
				{
					playerEffects.IsEffectActive(this, activateFeedback: true, enqueueFeedback: false);
				}
			}
			if (source == null)
			{
				source = playerEffects.gameObject;
				SpriteControl spriteControl = playerEffects.GetComponent<SpriteControl>();
				if (!playerEffects.GetComponent<CorruptionStats>().IsDefeated())
				{
					spriteControl.PlayAnimationForcedIfSpecificAnimationIsNotPlaying(AnimationType.Critical, AnimationType.Dodge, AnimationChangeType.ReturnToIdleAnimation);
				}
				else
				{
					spriteControl.PlayAnimationForcedIfSpecificAnimationIsNotPlaying(AnimationType.Critical, AnimationType.Dodge, AnimationChangeType.StayInTheNewAnimationNotLooping, delegate
					{
						spriteControl.PlayAnimationForced(AnimationType.ReceiveDamage, AnimationChangeType.StayInTheNewAnimationNotLooping);
					});
				}
			}
			SpawnVFX(GetVFXOwnerPosition(source), 3f);
			if (IsVFXEnabled())
			{
				PlayEffectActivationSFX();
			}
			return GetCriticalPurify(purifyAmount, sentPur, source);
		}
		CriticalMultiplierConfuseAction = false;
		return purifyAmount;
	}

	public int GetCriticalMultiplierAmount()
	{
		int num = 0;
		if (base.isOnBattleScene)
		{
			PlayerEffects component = ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>();
			num = component.IsEffectActiveGetAmount(criticalMultiplierEffect, activateFeedback: false);
			if (CriticalMultiplierConfuseAction)
			{
				num += component.IsEffectActiveGetAmount(criticalMultiplierConfuseEffect);
			}
		}
		return criticalMultiplierStartingAmount + num;
	}

	private int GetCriticalPurify(int amount, bool sentPur, GameObject source)
	{
		int num = 0;
		if (CriticalSafeDie && !sentPur)
		{
			num = celestialDewOmenData.MultiplierIncreaseAmount;
		}
		else if (!ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayer(source))
		{
			num = ReferenceSingleton<AustraOmensHandler>.Instance.IsHiveModuleOmenActivateGetCriticalMultiplierModifierAmountAndPlayFeedback();
		}
		return amount * (GetCriticalMultiplierAmount() + num);
	}

	public void CheckConfuseCriticalAndRemoveCriticalMultiplierConfuseEffect()
	{
		if (CriticalMultiplierConfuseAction)
		{
			ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>().RemoveEffect(criticalMultiplierConfuseEffect);
			CriticalMultiplierConfuseAction = false;
		}
	}
}
